// Static question data and indexes, built once at module load.
// Source files are generated by tools/import_xlsx.py — do not hand-edit them.
import questions from '../data/questions.json';
import lists from '../data/lists.json';
import legacyIds from '../data/legacyIds.json';
import { ymd } from './date';

export const QUESTIONS = questions;
export const BY_ID = new Map(questions.map((q) => [q.id, q]));
export const LISTS = lists;
export const LIST_KEYS = ['blind75', 'neetcode150', 'striver'];

export const DIFFICULTIES = ['Easy', 'Medium', 'Hard'];
export const DIFF_XP = { Easy: 40, Medium: 80, Hard: 160 };

// Sections in sheet order, each with its topics and an assigned gate rank.
export const SECTIONS = (() => {
  const map = new Map();
  for (const q of questions) {
    if (!map.has(q.section)) map.set(q.section, { name: q.section, questions: [], topics: new Map() });
    const s = map.get(q.section);
    s.questions.push(q);
    if (!s.topics.has(q.topic)) s.topics.set(q.topic, []);
    s.topics.get(q.topic).push(q);
  }
  const weight = { Easy: 1, Medium: 2, Hard: 3 };
  const sections = [...map.values()].map((s) => ({
    ...s,
    topics: [...s.topics].map(([name, qs]) => ({ name, questions: qs })),
    avg: s.questions.reduce((a, q) => a + weight[q.difficulty], 0) / s.questions.length,
  }));
  // Rank gates by average difficulty so the spread is E..S across the 13 sections.
  const ladder = ['E', 'E', 'D', 'D', 'C', 'C', 'C', 'B', 'B', 'A', 'A', 'S', 'S'];
  [...sections]
    .sort((a, b) => a.avg - b.avg)
    .forEach((s, i) => { s.rank = ladder[Math.min(i, ladder.length - 1)]; });
  return sections;
})();

// Old builds keyed progress by LeetCode number; map those onto slugs.
export const migrateCompleted = (raw) => {
  if (!raw) return {};
  const fallback = ymd();
  const entries = Array.isArray(raw) ? raw.map((id) => [id, fallback]) : Object.entries(raw);
  const out = {};
  for (const [id, date] of entries) {
    const key = legacyIds[id] || String(id);
    if (!out[key] || date < out[key]) out[key] = date;
  }
  return out;
};
